const n=[{slug:"selenix",name:"Selenix",tagline:"A browser-automation IDE where an AI assistant writes, runs and repairs the tests",summary:"A desktop browser-automation tool with an AI assistant that writes, runs and fixes tests from plain English, plus the site that licenses it.",engagement:"In-house product",status:"Live",categories:["desktop","web","ai"],timeline:"2025 – 2026",role:"Product design, desktop and web engineering, AI integration",platforms:["Windows","macOS","Linux","Web"],stack:["Electron","TypeScript","React","Selenium WebDriver","Laravel","Vue 3","Filament","PayPal","Node.js"],challenge:["Selenix began as our fork of the open-source Selenium IDE, a record-and-playback tool for browser tests. Recorded tests break when a page changes, and repairing them means reading selectors and editing steps by hand, which most people who need automation cannot do.","Selling the product was a second problem. Accounts, subscriptions, license keys and daily AI quotas all live outside the desktop app, and the app itself must never hold an AI provider key on the user's machine."],built:["An AI assistant runs a tool-calling loop and an auto-run cycle: generate, run, inspect results, fix, re-run, up to 5 passes.","The fork's command catalog now totals 114, including the scraping, HTTP, email, file and AI commands we added.","A scheduler runs tests once, hourly, daily, weekly or monthly, and tests export to C#, Java, JavaScript, Python and Ruby.","Tests play back in the built-in browser or in the user's own Chrome through an extension built on Manifest V3.","The web platform handles accounts, PayPal subscriptions across three plans, daily AI quotas and license keys inside the download, next to a template marketplace.","An OpenAI-compatible AI proxy keeps provider keys off the desktop, and a local Model Context Protocol (MCP) bridge exposes the app to outside AI clients."],results:[{value:"114",label:"automation commands"},{value:"5",label:"code-export languages"},{value:"3",label:"subscription plans"}],nextSteps:[],diagram:{src:"/img/portfolio/selenix/diagram",alt:"Selenix architecture: the desktop IDE with its AI assistant, automation engine and MCP bridge, connected to the AI proxy, selenix.io and two browser backends",caption:"The AI assistant drives the same engine you use by hand; the cloud side handles accounts, plans and AI access.",width:1600,height:900},cover:{src:"/img/portfolio/selenix/cover",alt:"The Selenix IDE after a scraping test run, with the books.toscrape.com catalogue page it visited",width:1600,height:900},gallery:[{src:"/img/portfolio/selenix/ide-run",alt:"Selenix test editor with every step of a scraping test marked as passed and the run log below",caption:"A finished run: each step passes and the log shows what the scraper found.",width:1600,height:900},{src:"/img/portfolio/selenix/playback",alt:"The books.toscrape.com catalogue page opened by a Selenix test during playback",caption:"Playback drives a real browser page, here the practice catalogue the demo scrapes.",width:1600,height:900},{src:"/img/portfolio/selenix/scheduler",alt:"Selenix scheduling dialog for running a test once or on a recurring schedule",caption:"Tests can run once or on an hourly, daily, weekly or monthly schedule.",width:1600,height:900},{src:"/img/portfolio/selenix/ai-assistant",alt:"The Selenix AI assistant panel next to a test, ready for a plain-English request",caption:"The AI assistant lives next to the test it is editing.",width:1600,height:900},{src:"/img/portfolio/selenix/selenix-io",alt:"The selenix.io home page: AI-powered browser automation, zero code required",caption:"selenix.io sells and licenses the app: accounts, plans and downloads.",width:1600,height:900}],videos:[],links:[{label:"selenix.io",href:"https://selenix.io"}],featured:!0,published:!0,order:1},{slug:"translation-api-platform",name:"Translation API platform for Xtensos",tagline:"A multi-tenant translation and generative-AI platform for Xtensos, on Kubernetes",summary:"A translation and generative-AI API, a file-translation workflow API and a web client for Xtensos, a language-services company, deployed on Kubernetes.",engagement:"Client engagement",status:"Live",categories:["apis","ai","web"],timeline:"2025 – 2026",role:"Backend and frontend engineering, DevOps, QA automation",platforms:["Web","REST API","Kubernetes"],stack:["Python","FastAPI","PostgreSQL","React 19","Express","Docker","Kubernetes","Azure"],challenge:["Xtensos needed two products in one platform: a translation and generative-AI API for developers, and a workflow API that runs a file through to a finished translation. Both had to serve several tenants from one deployment, with each tenant's keys, usage, memories and terminology kept apart.","Machine-translation throughput and language coverage pull against each other, and developer self-service has to sit next to corporate single sign-on. Every tenant needed both from the same deployment."],built:["Eight public API endpoints, behind per-tenant keys with usage metering per key and per end user, cover text and JSON translation, content generation and quality scoring.","Machine translation runs over pooled WebSocket connections per tenant, with caching and batching, next to a large language model (LLM) translation path.","Structured content generation runs through configurable assistants defined by prompt, JSON schema and temperature.","A file workflow splits each job by file and target language, applies translation memory and terminology, then routes to human or AI post-editing.","Single sign-on with Microsoft Entra ID and two-factor login with time-based one-time password (TOTP) codes, in a web client that speaks five languages.","Text round-trips as XLIFF, JSON and text and is extracted from PDF, DOCX, XLSX, PPTX and HTML; Docker images deploy to Kubernetes production and sandbox."],results:[{value:"8",label:"public API endpoints"},{value:"43",label:"workflow API routes"},{value:"5",label:"interface languages"}],nextSteps:[],diagram:{src:"/img/portfolio/translation-api-platform/diagram",alt:"The platform: a web client and API customers call the translation API and the file workflow API, backed by GPU machine-translation engines, an LLM and storage",caption:"Two FastAPI services share the work: instant text and generation, and file jobs.",width:1600,height:900},cover:{src:"/img/portfolio/translation-api-platform/cover",alt:"The platform's authoring screen: a content-generation prompt above a source and translation editor",width:1600,height:900},gallery:[{src:"/img/portfolio/translation-api-platform/sign-in",alt:"The Xtensos platform sign-in screen with single sign-on",caption:"Sign-in with Microsoft Entra ID single sign-on, or a password and a one-time code.",width:1600,height:900},{src:"/img/portfolio/translation-api-platform/quick-translate",alt:"Quick-translate screen with language pickers, machine-translation options and an AI enhance control",caption:"Quick translation with optional AI post-editing.",width:1600,height:900},{src:"/img/portfolio/translation-api-platform/translation-jobs",alt:"Translation jobs list with status, source and target languages",caption:"File jobs are split per file and target language and tracked to completion.",width:1600,height:900},{src:"/img/portfolio/translation-api-platform/translation-memories",alt:"Translation memory settings with a TMX upload form and memories grouped by tag",caption:"Translation memories and terminology are managed per customer.",width:1600,height:900}],videos:[],links:[],featured:!0,published:!0,order:2},{slug:"selenix-mcp-server",name:"Selenix MCP Server",tagline:"Let an AI assistant read, edit and run browser tests in Selenix, then fix what failed",summary:"A Model Context Protocol (MCP) server that lets Claude, or any MCP client, read, change and run real browser tests in Selenix.",engagement:"In-house product",status:"Live",categories:["ai","apis","desktop"],timeline:"Mar 2026",role:"Protocol design, TypeScript engineering, packaging",platforms:["npm","Windows","macOS","Linux"],stack:["TypeScript","Node.js","MCP SDK","esbuild"],challenge:["An AI assistant can suggest a browser test, but it cannot see what happened when that test runs. Without that feedback a failing step stays broken, and the model repeats the same guess.","Giving a model that access means a bridge between an MCP client and a desktop app that restarts often. A connection pinned to one launch breaks the moment the app restarts, and a bridge on a local machine must not hand out a standing credential."],built:["We published @selenix/mcp-server on npm as one bundled file: 18 tools, 14 to inspect and 4 to change.","Read tools return the project, tests, commands, page HTML, screenshots, step results and logs.","The four write tools add, replace and fix commands and run a test.","Calls go over HTTP on localhost to a bridge inside Selenix, whose bearer token changes on every launch.","The token is re-read before every call, so restarting Selenix never breaks the client, and screenshots come back as images.","A test run waits up to two minutes and returns a pass or fail for every step, and the server is listed in a public MCP directory."],results:[{value:"18",label:"MCP tools"},{value:"14",label:"read tools"},{value:"4",label:"write and run tools"}],nextSteps:[],diagram:{src:"/img/portfolio/selenix-mcp-server/diagram",alt:"How an MCP client reaches Selenix: stdio to the MCP server, HTTP with a token to the app's local bridge, then the session controllers and the browser",caption:"Every tool call is a local HTTP request to the running Selenix app.",width:1600,height:900},cover:{src:"/img/portfolio/selenix-mcp-server/cover",alt:"A Claude Code session calling Selenix MCP tools to list tests, run one and read its results",width:1600,height:900},gallery:[{src:"/img/portfolio/selenix-mcp-server/ide-after-run",alt:"Selenix showing the test Claude started over MCP, with every step passed",caption:"The same run, seen in Selenix: Claude started it through the MCP server.",width:1600,height:900},{src:"/img/portfolio/selenix-mcp-server/npm-package",alt:"The @selenix/mcp-server page on npm: version 1.0.7, public, with the install command",caption:"Published on npm, so any MCP client can install it with one command.",width:1600,height:900}],videos:[],links:[{label:"npm package",href:"https://www.npmjs.com/package/@selenix/mcp-server"}],featured:!1,published:!0,order:3},{slug:"element-140",name:"Element 140",tagline:"A first-person shooter set in a 103-meter-deep underground colony",summary:"A first-person shooter in Unreal Engine 5.7, set in a vertical underground colony, with custom C++ enemies and destructible props.",engagement:"In-house product",status:"In development",categories:["games"],timeline:"Jul 2026 – present",role:"Game design, C++ and Blueprint engineering, level building, AI-assisted art",platforms:["Windows (PC)"],stack:["Unreal Engine 5.7","C++","Blueprints","StateTree","Chaos physics","Niagara"],challenge:["Element 140 is a first-person shooter set in an underground colony hub. The hub is one tall space about 120 m across and 103 m deep, ten decks on a 9 m rhythm joined by a single spiral stair, and it holds around 8,500 actors in a single level.","A level that dense constrains everything added to it: sight lines, navigation, performance and the player's sense of where they are all have to survive the next prop. Off-the-shelf enemies would look off-the-shelf, so we built our own, and for a small team the pipeline that produces the content matters as much as the gameplay."],built:["The Mech Dog, a robotic enemy in C++ with a procedural four-legged gait, damage per body part, and parts that break off as physics debris.","A laser lock-on telegraph on the dog, and the Mech Trooper: a humanoid enemy animated with retargeted motion-capture clips.","Machine AI shared by both enemies in C++ with StateTree, including wave spawners and target sharing.","76 destructible props from one parent Blueprint, in light, heavy and fixed classes.","A combat heads-up display (HUD) drawn from C++, with crosshairs.","A flashlight on its own input, and colonists who walk the decks so the hub is populated between fights."],results:[],nextSteps:["Build the playable defense mission on the lower decks.","Add level streaming so the full hub loads in pieces.","Produce a packaged build for playtests."],diagram:null,cover:{src:"/img/portfolio/element-140/cover",alt:"A garden atrium inside the underground colony, with trees in round planters under a hexagonal skylight",width:1280,height:720},gallery:[{src:"/img/portfolio/element-140/atrium-spiral",alt:"The spiral staircase winding around its central column through several decks of the colony shaft, past lit walkways, fan housings and a garden deck",caption:"The spiral stair from the side: one continuous staircase climbs the 103-meter shaft.",width:1600,height:900},{src:"/img/portfolio/element-140/shaft-from-above",alt:"Looking down the colony shaft: the spiral stair winding down past several decks and walkways",caption:"The spiral stair from the top of the shaft, turning down through the decks.",width:1600,height:900},{src:"/img/portfolio/element-140/spiral-stair",alt:"First-person view straight down the spiral stair's well, with lamps on the landings",caption:"Straight down the stair: one continuous spiral links all ten decks.",width:1600,height:900},{src:"/img/portfolio/element-140/canteen",alt:"A canteen hall with rows of tables under a hexagonal skylight and wide misty windows",caption:"Lived-in spaces make the colony feel inhabited before the fighting starts.",width:1600,height:900},{src:"/img/portfolio/element-140/arena",alt:"An indoor football pitch built into the colony under a skylight",caption:"A sports hall carved into the rock, two decks tall.",width:1280,height:720},{src:"/img/portfolio/element-140/colonnade",alt:"A curved colonnade walkway with round windows, lamps and planters along the shaft",caption:"The ring walkways that circle the shaft on every deck.",width:1600,height:900},{src:"/img/portfolio/element-140/control-room",alt:"A control room with rows of consoles under a large glowing world map",caption:"Set dressing that carries the story without a single line of dialog.",width:1280,height:720},{src:"/img/portfolio/element-140/sky-lounge",alt:"A lounge with neon wall lights facing a large window showing a cloudy sky",caption:"A lounge with a screen of open sky, deep underground.",width:1600,height:900},{src:"/img/portfolio/element-140/garden-deck",alt:"A garden deck at night with a lit red-leaf tree behind red scaffolding",caption:"Lighting does most of the storytelling on the garden decks.",width:1280,height:720},{src:"/img/portfolio/element-140/dome",alt:"Looking up at a blue glass dome with concrete ribs and ceiling lights",caption:"The dome at the top of the shaft.",width:1280,height:720},{src:"/img/portfolio/element-140/mech-dog",alt:"The Mech Dog enemy, a four-legged robot with a mounted gun, in a studio render",caption:"The Mech Dog enemy: 48 rigid parts on 38 bones, built for part-by-part damage.",width:1600,height:900},{src:"/img/portfolio/element-140/mech-dog-exploded",alt:"Exploded view of the Mech Dog showing its separate armor, gun and leg parts",caption:"Every part can break off as physics debris when it is shot.",width:1600,height:900},{src:"/img/portfolio/element-140/mech-trooper",alt:"The Mech Trooper, a humanoid robot soldier with a red visor, aiming its rifle",caption:"The Mech Trooper, the second machine enemy, with armor generated part by part.",width:1600,height:900}],videos:[],links:[],featured:!0,published:!0,order:4},{slug:"ai-game-pipeline",name:"AI game-asset pipeline",tagline:"A local, scripted pipeline from a prompt to an engine-ready game asset",summary:"The content pipeline behind Element 140: a scripted local route from a prompt to a textured, collision-ready asset in the Unreal Editor.",engagement:"In-house product",status:"Live",categories:["ai","games"],timeline:"Jul 2026 – present",role:"Pipeline design, Python and Blender automation, Unreal Editor tooling",platforms:["Windows"],stack:["Python","ComfyUI","FLUX.2","Hunyuan3D 2.1","Blender 5.1","Unreal Engine 5.7","MCP"],challenge:["A small team cannot buy or hand-model every prop a level needs. Public generators are not enough on their own either: a generated mesh arrives at the wrong scale, with no collision and texture maps the engine cannot use as they are.","So every step has to be scripted, checked and repeatable, from the prompt to a file the engine accepts. The pipeline also has to prove an asset is sound before a person plays with it."],built:["One command takes a prompt to a mesh, textures and an engine-ready file staged for import, in about 4–8 minutes; one full end-to-end run took five and a half.","The generators are third-party models running locally on our GPU; the orchestration, export rules and checks are ours.","A fracture pipeline turns a static mesh into a destructible prop, with cell fracture in headless Blender, a reassembly check under 3 cm and convex collision.","Mechanical characters come from one JSON contract naming every bone, part and damage zone, read by the art, the export, the import check and the C++.","The Mech Trooper's armor was generated part by part: one FLUX.2 image per part, each turned into a textured mesh, fitted to the skeleton and baked into 4K texture atlases.","Mixamo animations are searched, downloaded, checked and retargeted by script.","Unreal Editor plugins developed by members of our team drive the editor over Model Context Protocol (MCP), and headless self-tests fire real projectiles before anyone plays the result."],results:[{value:"4–8 min",label:"from prompt to a textured, engine-ready prop"},{value:"76",label:"props made destructible by the fracture pipeline"},{value:"38 / 48",label:"bones / parts in the Mech Dog contract"}],nextSteps:[],diagram:{src:"/img/portfolio/ai-game-pipeline/diagram",alt:"The asset pipeline from concept art through 3D mesh, textures and headless Blender to the Unreal Editor and automated tests",caption:"Each stage hands a file to the next; nothing reaches a playtest without passing the self-tests.",width:1600,height:900},cover:{src:"/img/portfolio/ai-game-pipeline/cover",alt:"Side by side: the concept image of the robot dog and the finished 3D model rendered in Blender",width:1600,height:900},gallery:[{src:"/img/portfolio/ai-game-pipeline/texturing-bake-off",alt:"Three renders of the robot dog: the concept, a procedural PBR texture and an AI-painted texture",caption:"A bake-off between two texturing routes before committing to one.",width:1600,height:900},{src:"/img/portfolio/ai-game-pipeline/review-sheet",alt:"A grid of review renders of the robot dog from many angles, intact and damaged",caption:"The review sheet a person signs off before the model goes into the engine.",width:1600,height:900},{src:"/img/portfolio/ai-game-pipeline/damage-states",alt:"The robot dog rendered with damaged parts",caption:"Damage states are part of the model contract, not an afterthought.",width:1600,height:900},{src:"/img/portfolio/ai-game-pipeline/trooper-concepts",alt:"Four AI-generated concept images of a humanoid robot soldier with a red visor and a rifle",caption:"Mech Trooper concepts: four directions explored with FLUX.2 before one was picked.",width:1600,height:900},{src:"/img/portfolio/ai-game-pipeline/trooper-concept-vs-final",alt:"Side by side: the picked Mech Trooper concept and the finished 3D model",caption:"From the picked concept to the finished model.",width:1600,height:900},{src:"/img/portfolio/ai-game-pipeline/trooper-parts",alt:"Three views of the Mech Trooper's helmet, a generated armor part with a red visor slit",caption:"The armor is generated part by part: one image per part, then a textured mesh fitted to the skeleton.",width:1600,height:900},{src:"/img/portfolio/ai-game-pipeline/trooper-final",alt:"Three renders of the finished Mech Trooper: the inner frame, the armored body and an aiming pose",caption:"The finished Mech Trooper: inner frame, armor and an aiming pose.",width:1600,height:900},{src:"/img/portfolio/ai-game-pipeline/trooper-animation",alt:"Four frames of the Mech Trooper walking forward with its rifle raised",caption:"A retargeted walk, checked frame by frame before it goes into the engine.",width:1600,height:900},{src:"/img/portfolio/ai-game-pipeline/prop-reference-to-mesh",alt:"A stone portal: the AI reference image next to four views of the generated, textured 3D mesh",caption:"A prop from one command: reference image in, textured and engine-ready mesh out.",width:1600,height:900}],videos:[],links:[],featured:!1,published:!0,order:5},{slug:"zombie-stick-kill",name:"Zombie Stick Kill",tagline:"A wave-survival shooter inside a Reddit post, with server-checked high scores",summary:"A wave-survival shooter that plays inside a Reddit post, with more than 10,000 players and a leaderboard that checks every score on the server.",engagement:"In-house product",status:"Shipped",categories:["games","web"],timeline:"Sep 2025 – Jul 2026",role:"Game design, TypeScript engineering, backend, AI-assisted art",platforms:["Reddit (Devvit)","Web"],stack:["Phaser 3","TypeScript","Devvit","Express","Redis","Vite"],challenge:["The game runs inside a Reddit post, installed on a subreddit, with no store and no launcher between the player and it. Everything has to load and play in a webview on a platform we do not control.","A public leaderboard is the part that attracts cheating, and the client is the part an attacker controls. The backend runs on Reddit's serverless runtime with managed Redis, so the checks had to fit that runtime rather than a server of our own."],built:["Every run starts with a single-use token that the server expects back with the score.","Each submission is checked against that token, a plausible run duration and score ceilings derived from the game's own wave math.","Escalating waves with a boss every fifth wave, perk drafts before every third wave, two biomes, and five mutator waves such as night, fog and swarms.","Global and weekly leaderboards, personal bests and daily streaks, so the scores land somewhere.","New records post themselves to the subreddit automatically.","Six weapons and eight power-up types, with art from our local AI asset pipeline."],results:[{value:"10,000+",label:"players"},{value:"6",label:"weapons"},{value:"8",label:"power-up types"},{value:"5",label:"mutator waves"}],nextSteps:[],diagram:{src:"/img/portfolio/zombie-stick-kill/diagram",alt:"How the game runs on Reddit: the post opens the Phaser client, which talks to an Express server with Redis on Reddit's serverless runtime",caption:"Scores are checked on the server before they reach the leaderboard.",width:1600,height:900},cover:{src:"/img/portfolio/zombie-stick-kill/cover",alt:"Top-down Zombie Stick Kill gameplay: the player fighting a wave of zombies among barrels and fences",width:1600,height:900},gallery:[{src:"/img/portfolio/zombie-stick-kill/gameplay",alt:"Top-down gameplay with zombies, blood splatter, barrels and the score panel",caption:"Waves get faster and denser every level.",width:1600,height:900},{src:"/img/portfolio/zombie-stick-kill/title-screen",alt:"Zombie Stick Kill title screen with a zombie horde silhouette, how-to-play and leaderboard panels",caption:"Title screen from a local test build, so the leaderboard panel is empty; live scores are stored on Reddit.",width:1600,height:900},{src:"/img/portfolio/zombie-stick-kill/wave-start",alt:"A wave-start banner reading Wave 1, Fight",caption:"Short, punchy wave banners keep the pace up.",width:1600,height:900},{src:"/img/portfolio/zombie-stick-kill/reddit-app-page",alt:"Zombie Stick Kill's page on Reddit's developer platform, with the game's description and readme",caption:"The game's page on Reddit's developer platform.",width:1600,height:900}],videos:[],links:[{label:"Reddit app page",href:"https://developers.reddit.com/apps/zombiestickkill"}],featured:!1,published:!0,order:6},{slug:"frenamies",name:"Frenamies",tagline:"A party card game for one phone and two to twelve players",summary:"A party card game for two to twelve players sharing one phone: offline first, with the subscription, analytics and crash reporting a store release needs.",engagement:"In-house product",status:"In development",categories:["mobile"],timeline:"Jun – Jul 2026",role:"Product design, React Native engineering, content tooling, AI-assisted art",platforms:["Android","iOS"],stack:["Expo","React Native","TypeScript","Zustand","MMKV","RevenueCat","PostHog","Sentry"],challenge:["Frenamies is a party game for a group around one phone. 408 cards across three decks have to stay varied over a night of play, which a random draw does not guarantee: repeats, clumped intensity and a run of weak cards all show up quickly.","The app is built for the app stores, so it needs a subscription, analytics and crash reporting. It is also offline first, and it has to keep working when those third-party services are not configured or not reachable."],built:["Three decks plus a mixed mode, dealt as swipe cards with names filled in for 2–12 players.","A pure, unit-tested draw engine: filters for deck, intensity ceiling, player count and no repeats, then weighted intensity bands, anti-clumping rules, and better-rated cards surfacing first.","Eleven interactive mini-games play inside the card itself: a hot-potato bomb, a spin wheel, last finger down, a reaction duel, tug of war and more.","An age gate, plus an extra confirmation before the most intense level.","A subscription funnel with onboarding, a paywall with a free trial and restore; RevenueCat is the source of truth, with a cached entitlement for flaky launches.","Every third-party software development kit (SDK) disables itself when its key is missing, and an author-to-bundle content pipeline with deduplication and linting keeps the cards clean."],results:[{value:"408",label:"cards across three decks"},{value:"11",label:"interactive mini-games"},{value:"2–12",label:"players on one phone"}],nextSteps:["Set up store listings and launch accounts.","Give the newest mini-games a hands-on device pass.","Write more cards per deck."],diagram:{src:"/img/portfolio/frenamies/diagram",alt:"Frenamies architecture: a content pipeline feeds bundled decks to the draw engine, mini-games and stores, with optional subscription, analytics and crash-reporting services",caption:"Every service is optional: the game runs offline even with none of them configured.",width:1600,height:900},cover:{src:"/img/portfolio/frenamies/cover",alt:"Three phone screens from the game: an action card with a timer, the Wheel of Fate mini-game and a question card",width:1600,height:900},gallery:[{src:"/img/portfolio/frenamies/mini-games-and-dares",alt:"A two-player reaction-duel mini-game and two light dare cards with the players' names filled in",caption:"Mini-games play inside the card, and players' names are filled into every prompt.",width:1600,height:900}],videos:[],links:[],featured:!1,published:!0,order:7},{slug:"babysleep",name:"BabySleep",tagline:"One tap to log sleep, and a next-nap prediction that learns from each baby",summary:"A baby sleep tracker with one-tap logging and a prediction of the next nap or bedtime that adapts to one baby's own patterns, shared between caregivers.",engagement:"In-house product",status:"In development",categories:["mobile","web"],timeline:"Jun – Jul 2026",role:"Product design, full-stack engineering, Android packaging",platforms:["Web (installable PWA)","Android"],stack:["React 18","TypeScript","Vite PWA","TanStack Query","Node.js","Express","MySQL","Web Push"],challenge:["A sleep tracker that only logs is a diary. Parents want the next nap or bedtime, and the age-based tables published for babies describe an average baby, not this one.","A useful prediction has to start from the age tables, anchor to the real last wake time, and shift as the baby's own history accumulates, without drifting far from what the tables say. The logging side has to work with one hand in a dark room, keep several caregivers' phones in agreement, and survive a phone that is offline."],built:["A one-tap timer with a live clock, plus manual entry and editing of past sleeps.","Naps and night sleep are classified automatically, and week and day timelines, a list and a summary report show the history.","SweetSpot starts from age-based wake windows interpolated on the baby's exact age and anchors them to the real last wake time.","The baby's own recent history blends in once a slot has three samples, with small capped adjustments after a short nap or a sleep deficit.","SweetSpot moves bedtime earlier when another nap no longer fits, and explains every prediction in plain language.","Push reminders with quiet hours, caregivers' phones kept in sync, offline use with queued changes replayed, a family code to invite, and one step that deletes everything."],results:[],nextSteps:["Release on Google Play through closed testing.","Support more than one baby per family."],diagram:{src:"/img/portfolio/babysleep/diagram",alt:"BabySleep architecture: an installable web app and its Android package sync with an Express API, which runs the SweetSpot engine and reminders over MySQL",caption:"The prediction runs on the server, so every caregiver's phone shows the same answer.",width:1600,height:900},cover:{src:"/img/portfolio/babysleep/cover",alt:"Three phone screens from BabySleep: creating a family, the SweetSpot prediction on the home screen and the weekly sleep report",width:1600,height:900},gallery:[{src:"/img/portfolio/babysleep/home-and-invite",alt:"The home screen with today's sleep totals, and the family code screen for inviting a caregiver",caption:"Totals for today, and a short code to invite a second caregiver. Shown with demo data.",width:1600,height:900},{src:"/img/portfolio/babysleep/settings",alt:"BabySleep settings on a phone: this device's caregiver name, SweetSpot notifications, and the baby's name and date of birth",caption:"Each phone names its caregiver and opts in to reminders. Demo data.",width:1600,height:900}],videos:[],links:[],featured:!1,published:!0,order:8},{slug:"easyace",name:"easyace.ai",tagline:"Self-hosted image, video and chat generation, billed per generation",summary:"A pay-as-you-go studio and OpenAI-style API for image, video and chat generation, run on our own GPU, with a public gallery.",engagement:"In-house product",status:"Live",categories:["ai","web","apis"],timeline:"Apr – Jun 2026",role:"Product design, backend engineering, GPU operations",platforms:["Web","REST API"],stack:["Python","FastAPI","PostgreSQL","HTMX","ComfyUI","Stripe","Docker"],challenge:["Hosted generation APIs resell someone else's compute, so the unit cost and the queue are not ours to set. Running the models ourselves means one GPU serving several diffusion models and a large language model (LLM), where every model switch stalls the queue behind it.","A self-hosted generator also fails in ways a hosted API hides: a CUDA crash can take the generator down mid-job while a paying customer waits. The service has to notice, restart and refund without a person waking up."],built:["Five generation models on one GPU: FLUX.2, FLUX.1 and SDXL for images, LTX-2.3 in a standard and a fast version for video, plus a local LLM for chat completions.","Video renders in two stages and is upscaled 2× to 1920×1088.","A GPU queue groups jobs by model so the card loads each model as rarely as possible.","A circuit breaker and a watchdog restart the generator after a CUDA crash, and failed jobs are refunded automatically.","One prepaid US dollar balance with atomic deductions, Stripe checkout with three top-up tiers, and a $2 trial after email verification.","Live progress over server-sent events, a public gallery with a not-safe-for-work (NSFW) blur and an age gate, and a library of low-rank adaptation (LoRA) style adapters imported from a public model hub."],results:[{value:"5",label:"image and video models"},{value:"76",label:"end-to-end tests"},{value:"$0.01",label:"per image, lowest price"}],nextSteps:[],diagram:{src:"/img/portfolio/easyace/diagram",alt:"easyace.ai architecture: studio and API clients call a FastAPI app with PostgreSQL, whose GPU queue drives ComfyUI and a local LLM",caption:"One queue in front of one GPU, grouped by model so jobs rarely wait for a reload.",width:1600,height:900},cover:{src:"/img/portfolio/easyace/cover",alt:"The easyace.ai landing page with model prices and calls to try the studio or read the API docs",width:1600,height:900},gallery:[{src:"/img/portfolio/easyace/api-docs",alt:"The easyace.ai API documentation page with quick start, authentication and generation sections",caption:"An OpenAI-style API with its own documentation.",width:1600,height:900}],videos:[],links:[{label:"easyace.ai",href:"https://easyace.ai"}],featured:!1,published:!0,order:9},{slug:"local-ai-inference",name:"Private AI inference on one GPU",tagline:"A 125-billion-parameter AI model running privately on one gaming GPU",summary:"We run Qwen3.8-Flash-Next, a 125B mixture-of-experts model, on one RTX 5090 with the open-source Strata engine, sharing the card with a paid service.",engagement:"In-house product",status:"Live",categories:["ai","apis"],timeline:"Aug – Oct 2026",role:"Inference setup, benchmarking, GPU scheduling, agent tooling",platforms:["Windows","NVIDIA CUDA"],stack:["Strata","Qwen3.8-Flash-Next","CUDA","llama.cpp","Python","PowerShell"],challenge:["We wanted a coding model that reads a whole repository and answers to us alone, so no code leaves the building. A 125-billion-parameter model normally needs a server with hundreds of gigabytes of GPU memory, and one graphics card has 32 GB.","The same card already runs our paid image and video service, and customers come first. So every setting had to be measured rather than assumed, and the model has to give the GPU back the moment a paying job arrives."],built:["Strata, the open-source engine built for this model, spreads its 24,576 experts across the whole PC: the most-used on the GPU, every one pinned in RAM, and a 28.8 GB n-gram table on the SSD.","An adaptive expert cache fills the rest of the GPU and learns which experts the conversation needs; on our card it holds about 5,500, and 80–86% of expert reads hit it.","The CPU computes the experts the GPU does not hold at the same time as the GPU works, so neither waits for the other.","Multi-token prediction (MTP) drafts up to three tokens and one pass checks them: 2.4–3.2 tokens per pass, the same answer as normal decoding, 1.6–1.8× sooner.","Long prompts are read 8,192 tokens at a time while the next layer's experts stream in; on our RTX 5090 that is over 5,700 tokens per second.","It serves the OpenAI, Anthropic Messages and Responses APIs and reads images, so Claude Code, Codex CLI and the coding agent we use connect without adapters.","We benchmarked nine configurations from 32K to 256K tokens of context and chose the 3-bit build: the fastest, and it passed every coding check.","A GPU gate we wrote starts the model on demand and hands the card to our paid generation service when a customer job arrives, then takes it back."],results:[{value:"160 tok/s",label:"writing speed, 128K-token context window"},{value:"5,700+ tok/s",label:"reading a 113K-token prompt"},{value:"18/18",label:"coding checks passed"},{value:"3/3",label:"long-context recall checks at 256K"}],nextSteps:[],diagram:{src:"/img/portfolio/local-ai-inference/diagram",alt:"Inside Strata: always-used layers and an adaptive expert cache on the GPU, all 24,576 experts pinned in RAM, an n-gram table on the SSD, and guess-then-check decoding",caption:"How Strata fits a 125B model on one card, from its documentation; the speeds on this page are our own measurements.",width:1600,height:900},cover:{src:"/img/portfolio/local-ai-inference/cover",alt:"Benchmark chart comparing generation speed and prompt-reading time of four model configurations on one RTX 5090",width:1600,height:900},gallery:[{src:"/img/portfolio/local-ai-inference/monitor",alt:"Strata's monitor on our RTX 5090: decode and prefill speed, 30.7 of 32 GB VRAM with 5,523 experts cached, PCIe Gen5, and recent requests with 80 to 86 percent VRAM hit rates",caption:"Live telemetry during a coding-agent session: 32K-token prompts, most expert reads served from VRAM.",width:1600,height:900},{src:"/img/portfolio/local-ai-inference/gpu-gate",alt:"A GPU gate in front of two local model engines on one RTX 5090, handing the GPU to the image service when a customer job arrives",caption:"The gate we wrote: customer jobs on our generation service always come first.",width:1600,height:900}],videos:[],links:[{label:"Strata on GitHub",href:"https://github.com/Niko1221/Strata"}],featured:!1,published:!0,order:10},{slug:"match-recap-videos",name:"ScorCorect match-recap videos",tagline:"Ten-second vertical match recaps: AI video made once, every match composited",summary:"Ten-second vertical match recaps for ScorCorect.ro, a football-predictions site: the AI video is generated once and every match is composited in code.",engagement:"Client engagement",status:"In development",categories:["ai","apis"],timeline:"Apr – May 2026",role:"Pipeline design, Python engineering, video compositing, API",platforms:["REST API","Vertical video"],stack:["Python","FastAPI","ComfyUI","LTX-2.3","Wan2.1","MoviePy","Pillow","SQLite"],challenge:["The brief was a stream of short vertical match recaps for social media. Generated match by match with a paid video model, that spend grows with the fixture list, and a diffusion model will not hold a scoreline, a flag or a headline exactly right.","Most of a recap does not need generation. The atmosphere is the same from match to match; only the information carried on top of it changes. The work was drawing that line and then running it as a service, with a real API and job state, rather than a script on one machine."],built:["Output is 720×1280 vertical, 10 seconds at 24 frames per second, H.264 with audio, composited in Python with Pillow and MoviePy.","Cinematic stadium and fireworks plates are generated once with LTX-2.3 video diffusion and cached as an asset library.","Each match composites its flags, a player cutout with automatic background removal, a headline, a score that counts up goal by goal, and a logo banner.","Any goal count is supported, and the first goal lands on the plate's first firework burst.","Three variants: two players, one player, and one player with a short AI-animated closing shot using Wan2.1 image-to-video.","A FastAPI job API covers submit, poll, download and delete over an async queue with SQLite state; standard variants need no GPU at request time."],results:[],nextSteps:["Harden the API for production use.","Add more templates, for pre-match and half-time recaps.","Run a review pass on the AI-animated variant's hit rate."],diagram:{src:"/img/portfolio/match-recap-videos/diagram",alt:"The recap pipeline: video plates generated once per template, then each match composited from match data and a player photo",caption:"The expensive diffusion work happens once; each match is composited.",width:1600,height:900},cover:{src:"/img/portfolio/match-recap-videos/cover",alt:"Three phone screens showing frames of a generated match-recap video, with demo fixtures: the score and a match-minute ring",width:1600,height:900},gallery:[{src:"/img/portfolio/match-recap-videos/diffusion-background",alt:"An AI-generated stadium at night with floodlights and a crowd, used as a video plate",caption:"One of the cached diffusion plates every recap is built on.",width:1600,height:900},{src:"/img/portfolio/match-recap-videos/more-matches",alt:"Three phone screens from recaps of other demo matches, each with its score and match-minute ring over a stadium plate",caption:"The same template across different matches and team colors. Demo fixtures and scores.",width:1600,height:900}],videos:[{src:"/img/portfolio/match-recap-videos/recap.mp4",poster:"/img/portfolio/match-recap-videos/recap-poster.webp",title:"Two-player match recap, Romania against Italy, 10 seconds",caption:"A complete recap from the two-player template: the score counts up goal by goal over AI-generated stadium plates. Demo fixture and score.",width:720,height:1280},{src:"/img/portfolio/match-recap-videos/recap-ai-closing.mp4",poster:"/img/portfolio/match-recap-videos/recap-ai-closing-poster.webp",title:"One-player match recap, Spain against Greece, with an AI-animated closing shot",caption:"The one-player variant: the closing seconds animate the player photo with Wan2.1 image-to-video. Demo fixture and score.",width:720,height:1280}],links:[],featured:!1,published:!0,order:11},{slug:"project-adam",name:"Project ADAM",tagline:"Answers that rest on reviewed knowledge, not on the model's memory",summary:"A knowledge AI where people contribute and vote on knowledge, a moderator approves it, and a language model answers by searching that reviewed knowledge.",engagement:"In-house product",status:"In development",categories:["ai","web"],timeline:"Dec 2025 – May 2026",role:"Architecture, Python backend, retrieval design, Laravel website",platforms:["Web","REST API"],stack:["Python","FastAPI","MySQL","Qdrant","sentence-transformers","OpenRouter","LM Studio","Laravel 10","Vue 3"],challenge:["Answers from a language model rest on memory nobody can inspect, correct or trace to a source. Retrieval helps only if what is retrieved can be trusted, which means every item has to be contributed, reviewed and correctable.","Community curation brings its own constraint: votes cannot be allowed to publish anything on their own, and the process still has to work without a moderator reading everything twice. The rules belong in the pipeline, not in someone's attention."],built:["Question answering runs on four retrieval tools and cites the knowledge it used, so answers rest on sources rather than memory.","Contributions arrive as additions, corrections, clarifications or sources, and are validated on entry.","Community votes move a contribution into moderation and a moderator approves it; votes alone never publish anything.","A correction supersedes the old item and removes its vectors, and an hourly job routes new facts from finished chats to a moderator.","One AI call turns approved text into a summary, chunked sections for long texts, entities and relationships.","MySQL holds the relational record across 13 tables including an entity and relationship graph; Qdrant holds vectors computed locally, and each AI stage can run hosted or local."],results:[],nextSteps:["Finish the core backend and its tests.","Ship a user-facing chat; today's interface is an internal console.","Deploy the backend for production."],diagram:{src:"/img/portfolio/project-adam/diagram",alt:"How Project ADAM answers: an agent searches reviewed knowledge in Qdrant and MySQL; contributions are voted on and approved by a moderator before analysis",caption:"Only knowledge a moderator approved is searchable.",width:1600,height:900},cover:{src:"/img/portfolio/project-adam/cover",alt:"The Project ADAM website home page",width:1600,height:900},gallery:[{src:"/img/portfolio/project-adam/roadmap",alt:"Project ADAM roadmap page showing the current phase, the community knowledge pipeline",caption:"The current phase is the knowledge pipeline described here.",width:1600,height:900},{src:"/img/portfolio/project-adam/contribute",alt:"Project ADAM contribute page with volunteer roles for compute and storage",caption:"The website explains the project and collects volunteer sign-ups.",width:1600,height:900}],videos:[],links:[{label:"projectadam.ai",href:"https://projectadam.ai"}],featured:!1,published:!0,order:12}],i=[{key:"all",label:"All"},{key:"web",label:"Web & SaaS"},{key:"mobile",label:"Mobile"},{key:"desktop",label:"Desktop"},{key:"ai",label:"AI & Automation"},{key:"games",label:"Games"},{key:"apis",label:"APIs & Infrastructure"}],r=["categories","platforms","stack","challenge","built","results","nextSteps","gallery","videos","links"],a=n.filter(e=>e.published!==!1).map(e=>({...Object.fromEntries(r.map(t=>[t,[]])),...e})).sort((e,t)=>(e.order??99)-(t.order??99));function l(e){return a.find(t=>t.slug===e)??null}function d(e){var t;return((t=i.find(o=>o.key===e))==null?void 0:t.label)??e}function h(e){const t=a.findIndex(o=>o.slug===e);return t===-1||a.length<2?{prev:null,next:null}:{prev:a[(t-1+a.length)%a.length],next:a[(t+1)%a.length]}}const s={Live:"bg-ink/85 text-positive ring-positive/40",Shipped:"bg-ink/85 text-accent-400 ring-accent-400/40","In development":"bg-ink/85 text-warning ring-warning/40"},c=new Proxy(s,{get:(e,t)=>e[t]??"bg-ink/85 text-content-muted ring-line"});export{i as C,d as c,l as g,h as n,a as p,c as s};
